 "content": "from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find the horizontal five-cell exemplar among the non-background cells.
    runs = []
    for r, row in enumerate(grid):
        c = 0
        while c < len(row):
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < len(row) and row[c] != bg:
                c += 1
            if c - start > 1:
                runs.append((r, start, row[start:c]))
    if not runs:
        return out
    # The exemplar is the longest non-background horizontal run.
    _, _, pattern = max(runs, key=lambda x: len(x[2]))
    width = len(pattern)
    half = width // 2
    # Single non-background cells of the marker color receive the exemplar.
    marker_color = None
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == bg:
                continue
            isolated = ((r == 0 or grid[r - 1][c] == bg) and
                        (r + 1 == len(grid) or grid[r + 1][c] == bg) and
                        (c == 0 or row[c - 1] == bg) and
                        (c + 1 == len(row) or row[c + 1] == bg))
            if isolated:
                marker_color = value
                break
        if marker_color is not None:
            break
    if marker_color is None:
        return out
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != marker_color:
                continue
            isolated = ((r == 0 or grid[r - 1][c] == bg) and
                        (r + 1 == len(grid) or grid[r + 1][c] == bg) and
                        (c == 0 or row[c - 1] == bg) and
                        (c + 1 == len(row) or row[c + 1] == bg))
            if isolated:
                start = c - half
                if start >= 0 and start + width <= len(row):
                    out[r][start:start + width] = pattern[:]
    return out
